begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_temp;
select no_plan();
insert into auth.users(id,email_confirmed_at) values (md5('history_a')::uuid,clock_timestamp()),(md5('history_b')::uuid,clock_timestamp());
insert into public.profiles(id,display_name) values(md5('history_a')::uuid,'History A'),(md5('history_b')::uuid,'History B');
insert into public.workout_sessions(id,owner_id,name,status,completion_status,started_at,finished_at)
select md5('history_w'||i)::uuid,md5('history_a')::uuid,case when i=1 then 'Ad-hoc workout' else 'Workout '||i end,case when i=2 then 'abandoned' else 'completed' end,case when i=1 then 'partial' when i=4 then 'full' else 'none' end,'2020-01-01'::timestamptz+i*interval '1 day','2020-01-01'::timestamptz+i*interval '1 day'+interval '1 hour' from generate_series(1,25) i;
insert into public.workout_sessions(id,owner_id,name,status,completion_status,started_at,finished_at) values(md5('history_foreign')::uuid,md5('history_b')::uuid,'Private foreign','completed','full','2025-01-01','2025-01-02');
insert into public.workout_exercises(id,owner_id,workout_session_id,position,exercise_id,exercise_name_snapshot) select md5('history_e1')::uuid,md5('history_a')::uuid,md5('history_w1')::uuid,1,id,'Original bench snapshot' from public.exercises where slug='barbell_bench_press';
insert into public.workout_exercises(id,owner_id,workout_session_id,position,exercise_id,exercise_name_snapshot) select md5('history_e2')::uuid,md5('history_a')::uuid,md5('history_w1')::uuid,2,id,'Second bench snapshot' from public.exercises where slug='barbell_bench_press';
insert into public.workout_sets(id,owner_id,workout_exercise_id,position,status,actual_reps,actual_weight_kg,entered_weight,entered_unit,completed_at) values(md5('history_s1')::uuid,md5('history_a')::uuid,md5('history_e1')::uuid,1,'completed',8,22.68,50,'lb','2020-01-02');
insert into public.workout_sets(owner_id,workout_exercise_id,position,status,set_type,actual_reps,actual_weight_kg,completed_at) values(md5('history_a')::uuid,md5('history_e1')::uuid,2,'completed','warm_up',10,20,'2020-01-02');
insert into public.workout_sets(owner_id,workout_exercise_id,position,is_automatic,inputs_confirmed,prescribed_reps_min,prescribed_reps_max,prescribed_weight_kg) values(md5('history_a')::uuid,md5('history_e1')::uuid,3,true,false,999,999,999);
insert into public.workout_sets(owner_id,workout_exercise_id,position,status,actual_reps,actual_weight_kg,completed_at,deleted_at) values(md5('history_a')::uuid,md5('history_e1')::uuid,4,'completed',99,100,'2020-01-02','2020-01-03');
insert into public.workout_sets(owner_id,workout_exercise_id,position,status,actual_reps,actual_weight_kg,completed_at) values(md5('history_a')::uuid,md5('history_e2')::uuid,1,'completed',12,25,'2020-01-02');
insert into public.exercises(id,owner_id,name,exercise_type,archived_at) values(md5('history_custom')::uuid,md5('history_a')::uuid,'Archived custom','compound','2020-01-01');
insert into public.workout_exercises(id,owner_id,workout_session_id,position,exercise_id,exercise_name_snapshot) values(md5('history_custom_e')::uuid,md5('history_a')::uuid,md5('history_w4')::uuid,1,md5('history_custom')::uuid,'My original custom name');
insert into public.workout_sets(owner_id,workout_exercise_id,position,status,actual_reps,actual_weight_kg,completed_at) values(md5('history_a')::uuid,md5('history_custom_e')::uuid,1,'completed',8,30,'2020-01-05');
select ok(not has_function_privilege('anon','public.workout_history(text,timestamptz,uuid,integer)','execute'),'anonymous history denied');
select ok(not has_function_privilege('service_role','public.exercise_history(uuid,timestamptz,uuid,integer)','execute'),'service history access not granted');
select ok((select bool_and(not prosecdef) from pg_proc where proname in('workout_history','exercise_history','exercise_logging_kind') and pronamespace='public'::regnamespace),'all history functions use invoker RLS');
select ok(not has_column_privilege('authenticated','public.workout_exercises','logging_kind','UPDATE'),'client cannot mutate measurement snapshot');
set local role authenticated;
select set_config('request.jwt.claims',json_build_object('sub',md5('history_a')::uuid,'role','authenticated')::text,true);
select is((select count(*)::int from public.workout_history()),21,'history limits its default page');
select is((select count(*)::int from public.workout_history('all',null,null,51)),25,'only caller workouts returned');
select is((select count(*)::int from public.workout_history('completed',null,null,51)),24,'completed filter means closed sessions, including partial work');
select is((select count(*)::int from public.workout_history('incomplete',null,null,51)),23,'incomplete filter excludes fully done and abandoned');
select is((select count(*)::int from public.workout_history('abandoned',null,null,51)),1,'abandoned filter explicit');
select is((select working_sets::int from public.workout_history('all',null,null,51) where id=md5('history_w1')::uuid),2,'completed working sets exclude warm-ups, deleted sets and suggestions');
select is((select warm_up_sets::int from public.workout_history('all',null,null,51) where id=md5('history_w1')::uuid),1,'warm-ups counted separately');
select is((select incomplete_sets::int from public.workout_history('all',null,null,51) where id=md5('history_w1')::uuid),1,'pending suggestions remain incomplete');
select is((select exercise_count::int from public.workout_history('all',null,null,51) where id=md5('history_w1')::uuid),2,'original visible exercise count retained');
select is((select id from public.workout_history('all',null,null,2) limit 1),md5('history_w25')::uuid,'history newest first');
select is((select id from public.workout_history('all','2020-01-25',md5('history_w24')::uuid,2) limit 1),md5('history_w23')::uuid,'keyset pagination advances without overlap');
select throws_ok($$select public.workout_history('all',null,null,100)$$,'22023',null,'unbounded page sizes denied');
select throws_ok($$select public.exercise_history((select id from public.exercises where slug='barbell_bench_press'),now(),null)$$,'22023',null,'malformed cursor pair denied');
select is((public.exercise_history((select id from public.exercises where slug='barbell_bench_press'))->>'total_sessions')::int,1,'same exercise repeated within a session counts one workout');
select is(jsonb_array_length(public.exercise_history((select id from public.exercises where slug='barbell_bench_press'))->'entries'->0->'sets'),3,'Look Back combines completed canonical sets in original selection order only');
select is(public.exercise_history((select id from public.exercises where slug='barbell_bench_press'))->'entries'->0->>'exercise_name_snapshot','Original bench snapshot','history snapshots remain original');
select is((public.exercise_history((select id from public.exercises where slug='incline_barbell_bench_press'))->>'total_sessions')::int,0,'related exercise variation never merged');
select is((public.exercise_history(md5('history_custom')::uuid)->>'total_sessions')::int,1,'archived own custom history remains accessible');
select is(public.exercise_history((select id from public.exercises where slug='barbell_bench_press'))->'entries'->0->'sets'->0->>'entered_weight','50.000000','original entered metadata retained');
select set_config('request.jwt.claims',json_build_object('sub',md5('history_b')::uuid,'role','authenticated')::text,true);
select is((public.exercise_history((select id from public.exercises where slug='barbell_bench_press'))->>'total_sessions')::int,0,'other owner cannot inspect canonical exercise performance');
select is((public.exercise_history(md5('history_custom')::uuid)->>'total_sessions')::int,0,'other owner cannot inspect private custom history');
select is((select count(*)::int from public.workout_history('all',null,null,51)),1,'foreign history list remains isolated');
select set_config('request.jwt.claims',json_build_object('sub',md5('history_a')::uuid,'role','authenticated')::text,true);
select set_config('body_test.history_active',public.start_ad_hoc_workout()::text,true);
select is((select name from public.workout_sessions where id=current_setting('body_test.history_active')::uuid),'Workout','new workout friendly default without renaming old records');
select is((select name from public.workout_sessions where id=md5('history_w1')::uuid),'Ad-hoc workout','historical stored names unchanged');
select is(public.exercise_logging_kind((select id from public.exercises where slug='push_up')),'bodyweight','repetition bodyweight defaults explicitly supported');
select is(public.exercise_logging_kind((select id from public.exercises where slug='forearm_plank')),'duration','static holds do not fabricate reps');
select is(public.exercise_logging_kind((select id from public.exercises where slug='assisted_pull_up_machine')),'assisted','assistance not treated as added resistance');
select set_config('body_test.unsupported',public.edit_workout(current_setting('body_test.history_active')::uuid,'add',(select id from public.exercises where slug='forearm_plank'))::text,true);
select throws_ok($$select public.log_workout_set(current_setting('body_test.unsupported')::uuid,(select id from public.workout_sets where workout_exercise_id=current_setting('body_test.unsupported')::uuid order by position limit 1),'save',0,md5('history_bad_duration')::uuid,30,null,'working','bodyweight',true)$$,'22023',null,'duration completion rejected by database');
select is((select count(*)::int from public.workout_sets where workout_exercise_id=current_setting('body_test.unsupported')::uuid and status='completed'),0,'unsupported failure records no invented performance');
select is((public.exercise_history((select id from public.exercises where slug='barbell_bench_press'))->>'last_performed')::timestamptz,'2020-01-02'::timestamptz,'last performed uses actual completion timestamp rather than later session close');
select * from finish();
rollback;
